/**
 * secret-values.mjs - test credential values, assembled rather than stored.
 *
 * Same reasoning as fixtures/build-fixture.mjs: this repository is published,
 * and GitHub's push protection refuses any push containing a string shaped
 * like a live credential - including fabricated ones - and it scans history as
 * well as the tip.
 *
 * So the values below are constructed from parts at runtime. The resulting
 * strings are exactly the shape the scanner is supposed to catch; they are
 * not present as literals anywhere in the published tree.
 *
 * Every one of these points at nothing. There is no Stripe account, no AWS
 * account, no Slack workspace and no Supabase project behind them.
 */

import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));

/** base64url so a generated JWT has the shape of a JWT. */
const b64u = (s) => Buffer.from(s, "utf8").toString("base64url");

export function makeJwt(payload) {
  const header = b64u(JSON.stringify({ alg: "HS256", typ: "JWT" }));
  const body = b64u(JSON.stringify(payload));
  const signature = b64u("vibeaudit-demo-signature-grants-access-to-nothing");
  return `${header}.${body}.${signature}`;
}

/** A Stripe live secret key. */
export const STRIPE_LIVE_KEY = "sk_" + "live_" + "51QexampleEXAMPLEkeyEXAMPLEkey9876";

/** An AWS access key id (AWS's own documented example value). */
export const AWS_ACCESS_KEY_ID = "AKIA" + "IOSFODNN7EXAMPLE";

/** A Slack incoming-webhook URL. */
export const SLACK_WEBHOOK_URL =
  "https://hooks." + "slack.com/services/T0A1B2C3D4/B0E1F2G3H4/aBcDeFgHiJkLmNoPqRsTuVwX";

/** The Supabase public key. Public by design - it is not a finding on its own. */
export const SUPABASE_ANON_KEY = makeJwt({
  role: "anon",
  iss: "supabase",
  iat: 1735689600,
  exp: 2000000000,
});

/** The Supabase admin key. This one bypasses every row-level security policy. */
export const SUPABASE_SERVICE_ROLE_KEY = makeJwt({
  role: "service_role",
  iss: "supabase",
  iat: 1735689600,
  exp: 2000000000,
});

/** The path of the generated .env test fixture. */
export const ENV_FIXTURE_PATH = join(HERE, ".env");

/**
 * Write the .env fixture the scanner unit tests read.
 *
 * It is generated rather than committed for the same reason as the values
 * themselves: a committed file containing credential-shaped strings makes the
 * repository unpublishable.
 */
export function writeEnvFixture() {
  const body = `# ---------------------------------------------------------------------------
# test/fixtures/.env
#
# A test-only environment file, generated by secret-values.mjs. The keys are
# syntactically valid but point at nothing. Used by the secret-scanning unit
# tests.
# ---------------------------------------------------------------------------

VITE_SUPABASE_URL=https://exampleproject.supabase.co
VITE_SUPABASE_ANON_KEY=${SUPABASE_ANON_KEY}

SUPABASE_SERVICE_ROLE_KEY=${SUPABASE_SERVICE_ROLE_KEY}

STRIPE_SECRET_KEY=${STRIPE_LIVE_KEY}
SLACK_WEBHOOK_URL=${SLACK_WEBHOOK_URL}

# A placeholder value - the scanner must NOT report this one.
DEMO_API_KEY=your-api-key-here
`;
  mkdirSync(HERE, { recursive: true });
  writeFileSync(ENV_FIXTURE_PATH, body, "utf8");
  return ENV_FIXTURE_PATH;
}
